      "description": "A staff of water is most often made of driftwood, sometimes lacquered blue. Carved versions often have a wave pattern. The staff smells of rain or brine. While wielding a staff of water, you have resistance 5 to fire.\nActivate Cast a Spell\nEffect You expend a number of charges from the staff to cast a spell from its list.\n• Cantrip Spout\n• 1st Create Water, Hydraulic Push\n• 2nd Mist, Water Walk\n• 3rd Aqueous Orb, Wall of Water\nCraft Requirements Supply one casting of all listed ranks of all listed spells.",
