    "sourceHash": "sha256:208fe9b19421e3484cfc7dde0e5c54908504e1094ebd918402eb10894b2602db",
    "translatableHash": "sha256:f2359762dc118427059c436ad4a9aee35f9e2e66ac6f91a7dffa02618b1624f2",
    "data": {
      "schemaVersion": 1,
      "name": "Pipes of Compulsion (Greater)",
      "itemType": "equipment",
      "level": 8,
      "rarity": "uncommon",
      "traits": [
        "coda",
        "occult",
        "staff"
      ],
      "description": "These panpipes are made of what seems to be beat-up tin bound by frayed leather and look like they shouldn't function at all, but in skilled hands they emit a beautiful sound that beguiles the senses. While playing the pipes, you gain a +1 item bonus to Diplomacy and Performance checks.\nActivate Cast a Spell\nEffect You expend a number of charges from this instrument to cast a spell from its list.\n• Cantrip Daze\n• 1st Charm, Command, Fear\n• 2nd Laughing Fit, Stupefy\n• 3rd Charm, Hypnotize, Mind Reading, Ring of Truth\nCraft Requirements Supply one casting of all listed ranks of all listed spells.",
      "bulk": 0.1,
      "price": {
        "gp": 460
      },
      "usage": "held-in-two-hands",
      "category": "equipment",
      "group": "equipment"
    }
