    "sourceHash": "sha256:6d32a13559c1796c47a2c8a19a13fa98ad3a677ec796ba43955e5ca2732967de",
    "translatableHash": "sha256:4006e3ebe8c23f41c1d057ec1d1ebb65975e49422748d9da99ebbe45a15a4b65",
    "data": {
      "schemaVersion": 1,
      "name": "Sparking Spellgun (Moderate)",
      "itemType": "consumable",
      "level": 9,
      "rarity": "common",
      "traits": [
        "attack",
        "consumable",
        "fire",
        "magical",
        "spellgun"
      ],
      "description": "Activate 2 Strike\nA broad wooden tube with a handle, a sparking spellgun radiates warmth. You Activate the spellgun by aiming it at one creature and making your choice of a spell attack roll or a firearm attack roll against the target's AC. This spellgun has a range increment of 30 feet. The spellgun fires a small ball of sparks and fire, then crumbles to ash. The ball explodes in a flash when it hits, dealing 7d6 fire damage and 3d4 persistent fire damage.\nCritical Success The target takes double damage, takes double persistent damage, is Blinded for 1 round, and is Dazzled while the persistent damage lasts.\nSuccess The target takes full damage, full persistent damage, and is dazzled while the persistent damage lasts.",
      "bulk": 0,
      "price": {
        "gp": 150
      },
      "usage": "held-in-one-hand",
      "category": "other",
      "group": "consumable"
    }
