      "itemType": "equipment",
      "level": 9,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "A submersible helmet is a streamlined sallet with a visor and a flanged rear. While wearing the helmet with the visor down, you can see, hear, and speak clearly underwater. You also have a +1 item bonus to Athletics checks to Swim.\nActivate 3 (concentrate, manipulate)\nFrequency once per day\nEffect You can breathe underwater for 8 hours. During this time, you have a swim Speed equal to your land Speed.",
