      "itemType": "equipment",
      "level": 9,
      "rarity": "common",
      "traits": [
        "grimoire",
        "magical"
      ],
      "description": "This thick book has several colorful bookmarks and page dividers. Its title and text shift between numerous languages.\nActivate F (concentrate)\nFrequency once per day\nRequirements Your last action was to cast a spell prepared from this grimoire that allows understanding of another language, such as Translate or Truespeech\nEffect The grimoire absorbs knowledge of one language translated this way (caster's choice if more than one), allowing its bearer to communicate on a rudimentary level in that language even after the spell's duration has elapsed. The linguist's dictionary can hold one language at a time.",
