      "traits": [
        "alchemical",
        "consumable",
        "expandable"
      ],
      "description": "Activate 2 (manipulate)\nThis bottle contains a shrunken bird preserved with its feathers intact. When opened, the contents reconstitute into a Gargantuan effigy of a great roc, which can appear in the air instead of on the ground. The roc clutches up to two creatures, who become Grabbed, then Flies up to 90 feet and Releases the creatures. The targets must be within 15 feet of the roc; if any of them are unwilling to be grabbed, the roc must Grapple them with a 1d20+17 Athletics modifier or fail to pick them up.\nCraft Requirements Supply the corpse of a roc.",
