    "sourceHash": "sha256:4a8df6c206acef4f17654a6756f728b7a32c30ae9695a9440d1199c9890adf6a",
    "translatableHash": "sha256:fbcfd7ae1fd88807d63f133820ae144d5dd0f6cbcce1f820deeb6f4086a26ad4",
    "data": {
      "schemaVersion": 1,
      "name": "Library Robes",
      "itemType": "armor",
      "level": 9,
      "rarity": "common",
      "traits": [
        "inscribed"
      ],
      "description": "These +1 resilient scroll robes magically store a spell for you. During your daily preparations, choose one spell you know of 5th rank or lower. You inscribe that spell on the robes, as though you had done so using the robes' inscribed trait, but without needing to go through the normal scribing process. You must provide the minimum amount of materials to Craft one scroll of that spell (typically half the Price of a scroll of that rank plus any extra cost required for the spell). You don't need to be trained in Crafting, nor do you need the Magical Crafting feat. Using this ability erases any scroll already inscribed on the robe.",
      "bulk": 0.1,
      "price": {
        "gp": 700
      },
      "usage": "",
      "category": "unarmored",
      "group": "cloth",
      "armor": {
        "armorClassBonus": 0,
        "dexterityCap": 5,
        "checkPenalty": 0,
        "speedPenaltyFeet": 0
      }
    }
