    "data": {
      "schemaVersion": 1,
      "name": "Trackless (Greater)",
      "itemType": "equipment",
      "level": 10,
      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "Trackless runes are common among hunters and trappers, as well as thieves and anyone fleeing pursuit. While wearing trackless footwear, you have a +4 item bonus to the DC to track you. However, this bonus doesn't stack with the status bonus from Vanishing Tracks.\nActivate 2 (concentrate)\nFrequency once per day\nEffect You extend the effect of your rune out to a 20-foot emanation. The emanation remains for 8 hours, affecting up to 10 creatures of your choice within the area. You can Dismiss this effect.",
      "bulk": 0,
      "price": {
        "gp": 900
      },
      "usage": "applied-to-footwear",
      "category": "equipment",
      "group": "equipment"
    }
