      "itemType": "consumable",
      "level": 10,
      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable"
      ],
      "description": "Activate 1 (manipulate)\nIf fried, cast-off scales of a benthic worm render into crunchy snacks. Alchemists add reagents to the frying oil to enhance the scales' properties and flavor. For 1 minute after eating a delve scale, you gain a burrow Speed of 15 feet and a +2 item bonus to Athletics checks to High Jump or Long Jump.\nEffect: Delve Scale",
