      "rarity": "uncommon",
      "traits": [
        "backswing",
        "finesse",
        "reach",
        "sweep",
        "versatile-b"
      ],
      "description": "Metal caps the bottom of this +1 striking thundering dancer's spear and its point gives off the faint smell of ozone. If you hit a target that has been struck by a polarizing mace within the last round, you deal additional electricity damage to the target equal to the number of grounding spike's damage dice. If you critically hit such a target, the creature is Off-Guard until the start of your next turn.\nSpecial The grounding spike pairs with the Polarizing Mace.",
