    "sourceHash": "sha256:d461d4ffb2aee25133bf897ca8137c737914a020da94080fe9d1ef6f860323c7",
    "translatableHash": "sha256:8369a3200e4ea18b56add29a5bf4b012cdd62914e10b0adaeb555e90b1a9844d",
    "data": {
      "schemaVersion": 1,
      "name": "Wand of Chromatic Burst (4th-rank)",
      "itemType": "consumable",
      "level": 10,
      "rarity": "common",
      "traits": [
        "concentrate",
        "light",
        "magical",
        "manipulate",
        "wand"
      ],
      "description": "This intricately carved quartz wand changes color, cycling through the colors of the rainbow.\nActivate Cast a Spell\nFrequency once per day, plus overcharge\nEffect You cast 4th-rank Chromatic Armor. Additionally, the target can use the Chromatic Armor Burst action.\nChromatic Armor Burst 1 (concentrate, light, magical)\nRequirements You're affected by Chromatic Armor created by the wand of chromatic burst\nEffect Choose one color of the Chromatic Armor the wand created for you. The spell ends and light of that color flashes brightly in a 20-foot emanation. Creatures in the area take 4d6 untyped damage of the type associated with the color you chose, with a check (reflex, basic) save against your spell DC. This action has the trait corresponding to the damage type you chose.\nCraft Requirements Supply a casting of Chromatic Armor of the appropriate rank.",
      "bulk": 0.1,
      "price": {
        "gp": 1000
      },
      "usage": "held-in-one-hand",
      "category": "wand",
      "group": "consumable"
    }
