      "level": 10,
      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable",
        "healing"
      ],
      "description": "Ammunition round\nActivate 1 (manipulate)\nLife shot is a special cartridge that carries a small dose of elixir of life. A creature hit by activated life shot takes no damage from the successful attack, instead receiving 5d4+7 healing healing and gaining a +2 item bonus to saving throws against diseases and poisons for 1 minute. On a critical hit, roll the healing received twice and take the better result (this is a fortune effect). A target willing to be hit by this attack is Off-Guard against it.\nEffect: Life Shot",
