      "traits": [
        "magical",
        "spellheart"
      ],
      "description": "The golden religious symbol on the top of this spherical incense holder shifts its form to match the faith of its bearer. You gain no benefit from a judgment thurible if you don't worship a deity. The spell DC of any spell cast by activating this item is 27.\n• Armor After you cast a spell by activating the thurible, the thurible casts 3rd-rank Protection on you, with a duration of 1 round.\n• Weapon After you cast a spell by activating the thurible, the weapon gains a rune that lasts until the end of your next turn. It gains the Holy rune if your deity allows holy sanctification or the Unholy rune if your deity allows unholy sanctification. If your deity allows both, you can choose which rune the weapon gains. If your deity allows neither, your weapon doesn't gain a rune.\nActivate Cast a Spell\nEffect You cast Divine Lance.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Divine Wrath.",
