      "level": 11,
      "rarity": "common",
      "traits": [
        "alchemical",
        "cold",
        "consumable",
        "splash"
      ],
      "description": "Ammunition any\nActivate 1 (manipulate)\nWhen activated, the reservoir of alchemical reagents in elemental ammunition atomizes on impact, dealing 3d4 persistent cold damage to the target and 3 splash cold damage in addition to the damage the attack normally deals. Each damage type requires a different formula, and the ammunition gains a trait matching the damage type.",
      "bulk": 0,
