      "itemType": "equipment",
      "level": 11,
      "rarity": "common",
      "traits": [
        "invested",
        "magical"
      ],
      "description": "These goggles feature highly reflective lenses. While wearing the goggles, you gain a +2 item bonus to visual Perception checks and to saving throws against visual effects.\nActivate R (manipulate)\nTrigger A creature within 60 feet targets you with a visual effect\nEffect You turn your head to reflect aspects of the triggering effect back at its creator. The creature must attempt a check (fortitude, dc:30) save as it becomes disoriented by this reflection. On a failure, the creature is Sickened 1 (Sickened 2 on a critical failure). The creature is temporarily immune for 1 hour.",
      "bulk": 0,
      "price": {
        "gp": 1200
      },
      "usage": "worneyepiece",
      "category": "equipment",
