      "name": "Demolition Fulu (Moderate)",
      "itemType": "consumable",
      "level": 11,
      "rarity": "common",
      "traits": [
        "consumable",
        "fulu",
        "magical"
      ],
      "description": "A demolition fulu allows a saboteur or excavator to be far away from the scene when demolition happens. The fulu crumbles to ash over 5 minutes to 8 hours, as you determine when you place the fulu. Once the duration ends, the fulu lowers the Hardness of the object it's affixed to by an amount equal to the fulu's level and then deals 6d6 bludgeoning damage to the object. A demolition fulu serves as a hazard with a check (perception, dc:28) check to detect it and check (thievery, dc:28) check to disable it according to its type.",
