      "description": "The steely blue blade of this +2 striking frost rapier emerges from a hilt wrapped in thick leather and trimmed in fur to protect the wielder's hand.\nActivate 2 (concentrate, manipulate)\nFrequency once per day\nRequirements You hit a creature using the rime foil as your last action\nEffect You cast 5th-rank Phantom Prison on the target (check (will, dc:22, traits:action:disbelieve) to disbelieve). If the target has been damaged by a shattered plan in the last round, the DC is instead check (will, dc:24, traits:action:disbelieve).\nSpecial The rime foil pairs with the Shattered Plan.",
