      "name": "Serpent Oil (Major)",
      "itemType": "consumable",
      "level": 11,
      "rarity": "common",
      "traits": [
        "consumable",
        "magical",
        "oil"
      ],
      "description": "Activate 1 (manipulate)\nThis glistening oil has a green hue and tiny snake scales floating within. If you slather serpent oil on a Large object that is snakelike in shape, from a stick to a scarf, the object transforms into a Emperor Cobra, keeping some of the same colors and patterns of the original item. If placed on other objects, the oil fails and is wasted. This false snake has the minion trait. It remains in snake form for 1 minute before returning to its object state. If slain, the item returns to its original form, unharmed.",
