      "description": "The visages of beasts are carved into the painted wood of a beast staff, with a large head on top. When used as a weapon, the staff is a +2 striking staff. While wielding the staff while you have it prepared, you're affected by Speak with Animals. If you have Animal Empathy, you gain a +2 circumstance bonus on checks using it.\nActivate Cast a Spell\nEffect You expend a number of charges from the staff to cast a spell from its list.\n• Cantrip Gouging Claw\n• 1st Runic Body, Pest Form\n• 2nd Animal Form, Enlarge\n• 3rd Animal Form, Insect Form\n• 4th Animal Form, Bestial Curse, Insect Form, Pest Form\nCraft Requirements Supply one casting of all listed ranks of all listed spells.",
