      "itemType": "weapon",
      "level": 12,
      "rarity": "common",
      "traits": [
        "magical",
        "staff",
        "two-hand-d8"
      ],
      "description": "Geometric patterns are etched into the smooth brown-and-gray surface of a staff of earth, which makes a solid, resonant thud whenever tapped against the ground. While wielding a staff of earth, you gain a +1 circumstance bonus to your Fortitude saves and DC against effects that Shove you or knock you Prone.\nActivate Cast a Spell\nEffect You expend a number of charges from the staff to cast a spell from its list.\n• Cantrip Scatter Scree\n• 1st Pummeling Rubble\n• 2nd Expeditious Excavation, Pummeling Rubble\n• 3rd Earthbind, Shifting Sand\n• 4th Expeditious Excavation, Mountain Resilience, Shape Stone\n• 5th Blazing Fissure, Wall of Stone\nCraft Requirements Supply one casting of all listed ranks of all listed spells.",
