      "description": "Activate 1 (manipulate)\nMade from a special mixture of honey and alchemical reagents, poison fizz is a zesty, sweet rock candy that pops and crackles in your mouth. For 1 hour, you have a +2 item bonus to saving throws against poison and being petrified.\nSecondary Effect 2 (poison)\nEffect You bite the poison fizz to release its poisonous liquid center and spray green mist in a 15-foot cone. This deals 4d6 poison damage with a check (reflex, dc:29, basic, options:area-effect, traits:poison). A creature that critically fails is also Blinded until the end of your next turn and is then temporarily immune to being blinded by poison fizz for 1 hour.\nEffect: Poison Fizz",
