    "sourceHash": "sha256:5a7755f8355962425fb0e75db3b7f8d73e0d85c46036ecb9af620c514ac208eb",
    "translatableHash": "sha256:1b8f202413555568a0900bcaf3c9ca65bef696aadab0c9000716a5a1a4aab146",
    "data": {
      "schemaVersion": 1,
      "name": "Library Robes (Greater)",
      "itemType": "armor",
      "level": 12,
      "rarity": "common",
      "traits": [
        "inscribed"
      ],
      "description": "These +2 resilient scroll robes magically store a spell for you. During your daily preparations, choose one spell you know of 6th rank or lower. You inscribe that spell on the robes, as though you had done so using the robes' inscribed trait, but without needing to go through the normal scribing process. You must provide the minimum amount of materials to Craft one scroll of that spell (typically half the Price of a scroll of that rank plus any extra cost required for the spell). You don't need to be trained in Crafting, nor do you need the Magical Crafting feat. Using this ability erases any scroll already inscribed on the robe.",
      "bulk": 0.1,
      "price": {
        "gp": 2000
      },
      "usage": "",
      "category": "unarmored",
      "group": "cloth",
      "armor": {
        "armorClassBonus": 0,
        "dexterityCap": 5,
        "checkPenalty": 0,
        "speedPenaltyFeet": 0
      }
    }
