    "sourceHash": "sha256:c93da15fc82269a6a23e78af0e49a21137b0d41cfaf0d6368f634ca74c7eeb4f",
    "translatableHash": "sha256:f5128e353786317c8d9143688153d9b1bedc985b116fd101b76cbe66e816cdd7",
    "data": {
      "schemaVersion": 1,
      "name": "Bastion of the Inheritor",
      "itemType": "armor",
      "level": 12,
      "rarity": "uncommon",
      "traits": [
        "bulwark",
        "entrench-melee",
        "hindering"
      ],
      "description": "Worn by Iomedae's prestigious knights, this +2 resilient bastion plate is emblazoned with the Inheritor's religious symbol and sports a white cloak. While the cloak is white, this armor grants you a +2 item bonus to Diplomacy checks to Make an Impression, provided your target has no enmity toward Iomedae.\nActivate 1 (concentrate)\nEffect The armor's cloak becomes red for 1 minute. As long as the cloak is red, you gain the benefits of the armor's deflect melee trait without needing to spend an additional action to activate it during each turn.\nCraft Requirements You worship Iomedae.",
      "bulk": 5,
      "price": {
        "gp": 1750
      },
      "usage": "",
      "category": "heavy",
      "group": "plate",
      "armor": {
        "armorClassBonus": 6,
        "dexterityCap": 0,
        "checkPenalty": -3,
        "speedPenaltyFeet": -10
      }
    }
