      "level": 12,
      "rarity": "common",
      "traits": [
        "alchemical",
        "consumable",
        "injury",
        "poison"
      ],
      "description": "Activate 2 (manipulate)\nThis poison is named for the strain of fungi from which it's distilled. Hallucinations assail the victim's mind, causing them to see imaginary foes.\nSaving Throw check (fortitude, dc:32)\nMaximum Duration 6 rounds\nStage 1 3d8 poison damage, Off-Guard, and can't take reactions (1 round)\nStage 2 4d8 poison damage, off-guard, can't take reactions, Stunned 1 (1 round)\nStage 3 5d8 poison damage, off-guard, can't take reactions, and stunned 1 (1 round)",
