      "name": "Jolt Coil (Major)",
      "itemType": "equipment",
      "level": 12,
      "rarity": "common",
      "traits": [
        "electricity",
        "magical",
        "spellheart"
      ],
      "description": "Contained within this small glass tube is a twisted wire filament crackling with electricity, sending static prickling through the hair of anyone holding it. The spell DC of any spell cast by activating this item is 29.\n• Armor You gain resistance 5 to electricity.\n• Weapon After you cast an electricity spell by activating the coil, your Strikes with the weapon deal an additional 1d8 electricity damage until the end of your next turn.\nEffect: Jolt Coil - Armor\nEffect: Jolt Coil - Weapon\ncheck (reflex, dc:29, basic, name:Jolt Coil Spell, traits:spell, showDC:all)\nActivate Cast a Spell\nEffect You cast Electric Arc.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast 4th-rank Lightning Bolt.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Draw the Lightning.",
      "bulk": 0,
