      "description": "Activate r (concentrate)\nTrigger You are targeted by a spell of 5th rank or lower\nRequirements You're a master in Athletics, and you have the affixed shield raised.\nThis mirrored metal fragment is bolted or welded to the face of the affixed shield. When you Activate it, you attempt to reflect the triggering spell back at its caster with Spell Riposte, using your check (athletics) modifier for the counteract check. The talisman's counteract rank is 7th.",
