      "rarity": "common",
      "traits": [
        "magical"
      ],
      "description": "A complex pattern of protective symbols gives protection against various forms of energy, but only part of the runic structure can be active at a given time.\nActivateR (concentrate)\nFrequency once per hour\nTrigger You take acid, cold, electricity, or fire damage\nEffect You gain resistance 5 to the triggering damage type. This doesn't apply to the triggering damage. This resistance lasts until you Activate this rune again or the armor is no longer invested by you.\nEffect: Energy Adaptive",
