      "rarity": "uncommon",
      "traits": [
        "arcane",
        "capacity-3",
        "concussive",
        "fatal-d8",
        "fire"
      ],
      "description": "This +2 greater striking pepperbox cycles through several magical cores, swapping in new ones while the previous ones cool. The gun deals fire or electricity damage, alternating with each attack as it rotates cores. Arcadian gunslingers liken the rotating cores to a group of dancers sharing the spotlight.\nActivate 2 (manipulate)\nFrequency once per day\nEffect The spark dancer casts either Fireball or Lightning Bolt, depending on whether the current core would deal fire or electricity damage, as a 7th-rank arcane spell (check (reflex, dc:30, basic)).",
