      "traits": [
        "cold",
        "magical",
        "spellheart"
      ],
      "description": "Slowly spinning at the center of this crystalline orb is a single snowflake, and its surface remains lightly covered in frost no matter how hot the weather is outside. The spell attack modifier of any spell cast by activating this item is +20, and the spell DC is 30.\n• Armor You gain resistance 10 to cold.\n• Weapon After you cast a cold spell by activating the crystal, your Strikes with the weapon deal an additional 1d8 cold damage until the end of your next turn.\nEffect: Rime Crystal - Armor\nEffect: Rime Crystal - Weapon\nActivate Cast a Spell\nEffect You cast Frostbite.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Ice Storm.\nActivate Cast a Spell\nFrequency once per day\nEffect You cast Howling Blizzard.",
