      "itemType": "armor",
      "level": 13,
      "rarity": "common",
      "traits": [
        "flexible",
        "noisy"
      ],
      "description": "Instead of chain links, this +2 resilient chain shirt is assembled from metal \"leaves\" that each resemble a small blade.\nActivate 1 (manipulate)\nEffect You pull a link from the armor, which transforms into a +2 greater striking Dagger. The dagger disappears and reappears as a link in the armor after you Strike with it, or at the end of this turn if you don't make a Strike. You can Activate the blade byrnie in place of an Interact action to draw a weapon for abilities such as the Quick Draw feat.\nUpgrading the runes on the blade byrnie makes the daggers pulled from it more powerful. The daggers have a +2 weapon potency rune if the armor has a +2 armor potency rune, or a +3 weapon potency rune if the armor has a +3 armor potency rune.",
