    "sourceHash": "sha256:591c658c900d04316be003b08eea748576129baad031b8b6f0b9153af6c6dfcf",
    "translatableHash": "sha256:705cb61644ea55a282348e95796bbfb167eb7ab134cb7eb211d96c86a0d350ca",
    "data": {
      "schemaVersion": 1,
      "name": "Euphoric Loop (Greater)",
      "itemType": "consumable",
      "level": 13,
      "rarity": "common",
      "traits": [
        "catalyst",
        "consumable",
        "magical"
      ],
      "description": "Activate Cast a Spell\nThis catalyst is made from twisted sapling bark harvested under a full moon. When used to cast a Charm spell, the spell creates a blissful experience for all targets of the spell. When the spell ends, even if you Dismiss it, the sudden mental dissonance between the charmed state and reality forces all targets of the charm spell to attempt a Will save against your spell DC.\nCritical Success The target is unaffected.\nSuccess The target is Stunned 1 or, if the spell ended because of a hostile action, Confused for 1 round.\nFailure The target is Stunned 2 or, if the spell ended because of a hostile action, confused for 1 round.\nCritical Failure The target is Stunned 3 or, if the spell ended because of a hostile action, confused for 2 rounds.",
      "bulk": 0.1,
      "price": {
        "gp": 450
      },
      "usage": "held-in-one-hand",
      "category": "catalyst",
      "group": "consumable"
    }
