    "sourceHash": "sha256:2856870b1b34f7e1455fb33bdae04c48382733f30bbfcf6556aad1f84d7b4817",
    "translatableHash": "sha256:1aa2fd81aa1ec4cbc9aff3858e820999d19d2df368add0f80b213a4cb7b34b72",
    "data": {
      "schemaVersion": 1,
      "name": "Wand of Teeming Ghosts (6th-Rank)",
      "itemType": "consumable",
      "level": 14,
      "rarity": "uncommon",
      "traits": [
        "magical",
        "wand"
      ],
      "description": "This pale wooden wand is carved to resemble a thigh bone with metal caps at each end. Ghostly tendrils seem to swirl around it every so often.\nActivate Cast a Spell\nFrequency once per day, plus overcharge\nEffect You cast False Vitality at 6th-rank. During the duration of the spell, wisps that resemble spirits flit around you as long as you have any temporary Hit Points from false vitality, and you can use the following action.\nActivation F (concentrate)\nTrigger You successfully impart the Frightened 1 condition to a creature\nRequirements You have at least 1 temporary Hit Point from false vitality\nEffect You end false vitality and increase the creature's frightened condition value to 2.\nCraft Requirements Supply a casting of false vitality at 6th-rank",
      "bulk": 0.1,
      "price": {
        "gp": 4500
      },
      "usage": "held-in-one-hand",
      "category": "wand",
      "group": "consumable"
    }
